"use client";

import { useState } from "react";
import { saveListingDraft, saveVendorProfile, submitListing, submitVendorProfile } from "@/actions/vendor";

export function OnboardingForm() {
  const [step, setStep] = useState(1); const [notice, setNotice] = useState(""); const [listingId, setListingId] = useState("");
  async function business(formData: FormData) { await saveVendorProfile(Object.fromEntries(formData)); setNotice("Business details saved."); setStep(2); }
  async function listing(formData: FormData) { const result = await saveListingDraft({ ...Object.fromEntries(formData), priceFrom: formData.get("priceFrom") }); if (typeof result === "object" && "id" in result) setListingId(result.id); setNotice("Listing draft saved."); setStep(3); }
  async function submit() { await submitVendorProfile(); if (listingId) await submitListing({ id: listingId }); setNotice("Submitted for review. You can return to your vendor dashboard at any time."); }
  return <main className="auth-page"><section className="auth-panel"><p className="eyebrow">HOST ONBOARDING · STEP {step} OF 3</p><h1>{step === 1 ? "Tell us about your business." : step === 2 ? "Create your first draft." : "Ready for review."}</h1>{step === 1 && <form className="auth-form" action={business}><label><span>Business name</span><input name="businessName" required /></label><label><span>Description</span><textarea name="description" required /></label><label><span>Contact email</span><input name="contactEmail" type="email" required /></label><label><span>Contact phone</span><input name="contactPhone" required /></label><label><span>Address</span><input name="address" required /></label><button className="button button-dark">Save and continue</button></form>}{step === 2 && <form className="auth-form" action={listing}><label><span>Listing type</span><select name="type"><option value="accommodation">Accommodation</option><option value="tour">Tour</option><option value="activity">Activity</option><option value="restaurant">Restaurant</option></select></label><label><span>Title</span><input name="title" required /></label><label><span>Slug</span><input name="slug" placeholder="my-kenya-experience" required /></label><label><span>Description</span><textarea name="description" required /></label><label><span>Location</span><input name="location" required /></label><label><span>From price</span><input name="priceFrom" type="number" min="0" required /></label><label><span>Currency</span><input name="currency" defaultValue="KES" required /></label><button className="button button-dark">Save draft</button></form>}{step === 3 && <button className="button button-dark" onClick={() => void submit()}>Submit for review</button>}{notice && <p className="auth-hint">{notice}</p>}</section></main>;
}
